'use client';

const LOGO = 'data:image/png;base64,';
const STAMP = 'data:image/png;base64,';

const f = (n) => Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const sample = {
  no: 'PS2026/001',
  name: 'Ibrahim Ziyad 1',
  position: 'Waiter',
  month: 'November 2026',
  basic: 2000,
  bonus: 0,
  deduction: 150,
  note: 'Advance recovery',
  account: 'Bank (BML)',
  date: '30/11/2026',
  owner: 'Ali Azeem, Manager',
};
const net = sample.basic + sample.bonus - sample.deduction;

/* ── Option A: Clean minimal card ── */
function SlipA() {
  return (
        <div style={{ background:'#fff', borderRadius:20, width:'100%', maxWidth:400,
      boxShadow:'0 2px 24px rgba(0,0,0,0.08)', overflow:'hidden', fontFamily:'system-ui,sans-serif' }}>
      {/* header */}
      <div style={{ padding:'24px 24px 20px', borderBottom:'1px solid #f0ede9',
        display:'flex', justifyContent:'space-between', alignItems:'flex-start', background:'#8A7356' }}>

        <div>
          <img src={LOGO} alt="Logo" style={{ width:40, height:40, borderRadius:10, objectFit:'cover', marginBottom:12 }}/>
          <div style={{ fontSize:18, fontWeight:700, color:'#fff', letterSpacing:'-.02em' }}>{sample.name}</div>
          <div style={{ fontSize:13, color:'rgba(255,255,255,0.7)', marginTop:2 }}>{sample.position}</div>
        </div>
        <div style={{ textAlign:'right' }}>
          <div style={{ fontSize:11, color:'rgba(255,255,255,0.7)', fontWeight:600, letterSpacing:'.06em', textTransform:'uppercase', marginBottom:4 }}>Payslip</div>
          <div style={{ fontSize:13, fontWeight:600, color:'#fff' }}>{sample.no}</div>
          <div style={{ fontSize:12, color:'rgba(255,255,255,0.65)', marginTop:2 }}>{sample.month}</div>
        </div>
      </div>
      {/* net pay */}
      <div style={{ padding:'20px 24px', background:'#faf8f6', borderBottom:'1px solid #f0ede9' }}>
        <div style={{ fontSize:11, color:'#9a8880', fontWeight:600, letterSpacing:'.06em', textTransform:'uppercase', marginBottom:6 }}>Net pay</div>
        <div style={{ fontSize:32, fontWeight:700, color:'#1a1410', letterSpacing:'-.03em' }}>MVR {f(net)}</div>
      </div>
      {/* breakdown */}
      
      <div style={{ padding:'20px 24px', background:'#fff' }}>

        <div style={{ fontSize:11, color:'#9a8880', fontWeight:600, letterSpacing:'.06em', textTransform:'uppercase', marginBottom:12 }}>Breakdown</div>
        {[
          ['Basic salary', sample.basic, false],
          ...(sample.bonus > 0 ? [['Bonus', sample.bonus, false]] : []),
          ...(sample.deduction > 0 ? [[sample.note || 'Deduction', sample.deduction, true]] : []),
        ].map(([label, amount, isDeduct]) => (
          <div key={label} style={{ display:'flex', justifyContent:'space-between', alignItems:'center',
            padding:'10px 0', borderBottom:'1px solid #f5f2ef' }}>
            <span style={{ fontSize:13, color:'#5a4a42' }}>{label}</span>
            <span style={{ fontSize:13, fontWeight:600, color: isDeduct ? '#c0392b' : '#1a1410' }}>
              {isDeduct ? '− ' : ''}MVR {f(amount)}
            </span>
          </div>
        ))}
        <div style={{ display:'flex', justifyContent:'space-between', padding:'14px 0 0' }}>
          <span style={{ fontSize:14, fontWeight:600, color:'#1a1410' }}>Net pay</span>
          <span style={{ fontSize:14, fontWeight:700, color:'#c19a6b' }}>MVR {f(net)}</span>
        </div>
      </div>
      {/* meta */}
      
      <div style={{ padding:'0 24px 20px', display:'grid', gridTemplateColumns:'1fr 1fr', gap:12, background:'#fff' }}>

        {[['Payment date', sample.date], ['Period', sample.month]].map(([l, v]) => (
          <div key={l} style={{ background:'#faf8f6', borderRadius:10, padding:'10px 12px' }}>
            <div style={{ fontSize:10, color:'#9a8880', marginBottom:3 }}>{l}</div>
            <div style={{ fontSize:12, fontWeight:600, color:'#1a1410' }}>{v}</div>
          </div>
        ))}
      </div>
      {/* footer */}
     
      <div style={{ padding:'14px 24px', borderTop:'1px solid #f0ede9',
        display:'flex', justifyContent:'space-between', alignItems:'center', background:'#fff' }}>

        <div style={{ fontSize:11, color:'#9a8880', lineHeight:1.6 }}>
          Authorised by<br/><strong style={{ fontSize:12, color:'#1a1410' }}>{sample.owner}</strong>
        </div>
        <img src={STAMP} alt="Stamp" style={{ width:52, height:52, objectFit:'contain', opacity:.8 }}/>
      </div>
    </div>
  );
}

/* ── Option B: Two-tone with accent strip ── */
function SlipB() {
  return (
    <div style={{ background:'#fff', borderRadius:20, width:'100%', maxWidth:400,
      boxShadow:'0 2px 24px rgba(0,0,0,0.08)', overflow:'hidden', fontFamily:'system-ui,sans-serif' }}>
      {/* top strip */}
      <div style={{ background:'#1a1410', padding:'24px 24px 28px' }}>
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:20 }}>
          <img src={LOGO} alt="Logo" style={{ width:36, height:36, borderRadius:8, objectFit:'cover' }}/>
          <div style={{ textAlign:'right' }}>
            <div style={{ fontSize:11, color:'#c19a6b', fontWeight:600, letterSpacing:'.06em', textTransform:'uppercase' }}>Payslip · {sample.no}</div>
            <div style={{ fontSize:12, color:'rgba(255,255,255,0.5)', marginTop:3 }}>{sample.month}</div>
          </div>
        </div>
        <div style={{ fontSize:20, fontWeight:700, color:'#fff', letterSpacing:'-.02em' }}>{sample.name}</div>
        <div style={{ fontSize:13, color:'rgba(255,255,255,0.5)', marginTop:3 }}>{sample.position}</div>
        <div style={{ marginTop:20, background:'rgba(255,255,255,0.06)', borderRadius:12, padding:'14px 16px',
          display:'flex', justifyContent:'space-between', alignItems:'center' }}>
          <div style={{ fontSize:12, color:'rgba(255,255,255,0.5)' }}>Net pay</div>
          <div style={{ fontSize:24, fontWeight:700, color:'#c19a6b', letterSpacing:'-.02em' }}>MVR {f(net)}</div>
        </div>
      </div>
      {/* body */}
      <div style={{ padding:'20px 24px' }}>
        <div style={{ fontSize:11, color:'#9a8880', fontWeight:600, letterSpacing:'.06em', textTransform:'uppercase', marginBottom:12 }}>Breakdown</div>
        {[
          ['Basic salary', sample.basic, false],
          ...(sample.bonus > 0 ? [['Bonus', sample.bonus, false]] : []),
          ...(sample.deduction > 0 ? [[sample.note || 'Deduction', sample.deduction, true]] : []),
        ].map(([label, amount, isDeduct]) => (
          <div key={label} style={{ display:'flex', justifyContent:'space-between',
            padding:'10px 0', borderBottom:'1px solid #f5f2ef' }}>
            <span style={{ fontSize:13, color:'#5a4a42' }}>{label}</span>
            <span style={{ fontSize:13, fontWeight:600, color: isDeduct ? '#c0392b' : '#1a1410' }}>
              {isDeduct ? '− ' : ''}MVR {f(amount)}
            </span>
          </div>
        ))}
        <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:10, marginTop:16 }}>
          {[['Payment date', sample.date], ['Paid via', sample.account]].map(([l, v]) => (
            <div key={l} style={{ background:'#faf8f6', borderRadius:10, padding:'10px 12px' }}>
              <div style={{ fontSize:10, color:'#9a8880', marginBottom:3 }}>{l}</div>
              <div style={{ fontSize:12, fontWeight:600, color:'#1a1410' }}>{v}</div>
            </div>
          ))}
        </div>
      </div>
      {/* footer */}
      <div style={{ padding:'14px 24px', borderTop:'1px solid #f0ede9',
        display:'flex', justifyContent:'space-between', alignItems:'center' }}>
        <div style={{ fontSize:11, color:'#9a8880', lineHeight:1.6 }}>
          Authorised by<br/><strong style={{ fontSize:12, color:'#1a1410' }}>{sample.owner}</strong>
        </div>
        <img src={STAMP} alt="Stamp" style={{ width:52, height:52, objectFit:'contain', opacity:.8 }}/>
      </div>
    </div>
  );
}

/* ── Option C: Ultra minimal, light only ── */
function SlipC() {
  return (
    <div style={{ background:'#fff', borderRadius:20, width:'100%', maxWidth:400,
      boxShadow:'0 2px 24px rgba(0,0,0,0.08)', fontFamily:'system-ui,sans-serif',
      border:'1px solid #ede8e3' }}>
      <div style={{ padding:'28px 28px 0' }}>
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:28 }}>
          <img src={LOGO} alt="Logo" style={{ width:36, height:36, borderRadius:8, objectFit:'cover' }}/>
          <div style={{ fontSize:11, color:'#9a8880', fontWeight:500 }}>{sample.no} · {sample.month}</div>
        </div>
        <div style={{ fontSize:13, color:'#9a8880', marginBottom:4 }}>{sample.position}</div>
        <div style={{ fontSize:22, fontWeight:700, color:'#1a1410', letterSpacing:'-.02em', marginBottom:6 }}>{sample.name}</div>
        <div style={{ width:40, height:3, background:'#c19a6b', borderRadius:2, marginBottom:28 }}/>
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-end', marginBottom:28,
          paddingBottom:24, borderBottom:'1px solid #f0ede9' }}>
          <div>
            <div style={{ fontSize:11, color:'#9a8880', marginBottom:4 }}>Net pay</div>
            <div style={{ fontSize:28, fontWeight:700, color:'#1a1410', letterSpacing:'-.03em' }}>MVR {f(net)}</div>
          </div>
          <div style={{ textAlign:'right' }}>
            <div style={{ fontSize:11, color:'#9a8880', marginBottom:4 }}>Paid via</div>
            <div style={{ fontSize:13, fontWeight:600, color:'#1a1410' }}>{sample.account}</div>
          </div>
        </div>
        {[
          ['Basic salary', f(sample.basic), false],
          ...(sample.bonus > 0 ? [['Bonus', f(sample.bonus), false]] : []),
          ...(sample.deduction > 0 ? [[sample.note || 'Deduction', f(sample.deduction), true]] : []),
        ].map(([label, amount, isDeduct]) => (
          <div key={label} style={{ display:'flex', justifyContent:'space-between',
            padding:'9px 0', borderBottom:'1px solid #f5f2ef', fontSize:13 }}>
            <span style={{ color:'#5a4a42' }}>{label}</span>
            <span style={{ fontWeight:600, color: isDeduct ? '#c0392b' : '#1a1410' }}>
              {isDeduct ? '− ' : ''}MVR {amount}
            </span>
          </div>
        ))}
      </div>
      <div style={{ padding:'20px 28px 24px', display:'flex', justifyContent:'space-between', alignItems:'center', marginTop:4 }}>
        <div style={{ fontSize:11, color:'#9a8880', lineHeight:1.7 }}>
          {sample.date}<br/>
          <strong style={{ fontSize:12, color:'#1a1410' }}>{sample.owner}</strong>
        </div>
        <img src={STAMP} alt="Stamp" style={{ width:56, height:56, objectFit:'contain', opacity:.75 }}/>
      </div>
    </div>
  );
}

export default function Testing() {
  return (
    <div>
      <h1>Payslip designs</h1>
      <p style={{ color:'#9a8880', fontSize:13, marginBottom:32 }}>Three options — same data, different style. Tell me which one you prefer or what to mix.</p>
      <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit,minmax(300px,1fr))', gap:32, alignItems:'start' }}>
        <div>
          <div style={{ fontSize:12, fontWeight:600, color:'#9a8880', marginBottom:12, letterSpacing:'.04em', textTransform:'uppercase' }}>Option A — Clean minimal</div>
          <SlipA/>
        </div>
        <div>
          <div style={{ fontSize:12, fontWeight:600, color:'#9a8880', marginBottom:12, letterSpacing:'.04em', textTransform:'uppercase' }}>Option B — Dark header</div>
          <SlipB/>
        </div>
        <div>
          <div style={{ fontSize:12, fontWeight:600, color:'#9a8880', marginBottom:12, letterSpacing:'.04em', textTransform:'uppercase' }}>Option C — Ultra minimal</div>
          <SlipC/>
        </div>
      </div>
    </div>
  );
}

